const MAP_STATE_KEY = "civifix_map_state";

export function slugify(text = "") {
  return text
    .toString()
    .toLowerCase()
    .trim()
    .replace(/[^\w\s-]/g, "")
    .replace(/[\s_]+/g, "-")
    .replace(/-+/g, "-");
}

/** Human-readable URL: /issue/road-pothole-a1b2c3 */
export function getIssuePath(complaint) {
  if (!complaint?._id) return "/track-status";
  const tail = complaint._id.slice(-6);
  const cat = slugify(complaint.category || "issue");
  return `/issue/${cat}-${tail}`;
}

export function resolveComplaintId(slugOrId, complaints = []) {
  if (!slugOrId) return null;
  const direct = complaints.find((c) => c._id === slugOrId);
  if (direct) return direct._id;
  const byTail = complaints.find(
    (c) => slugOrId.endsWith(c._id.slice(-6)) || slugOrId.includes(c._id)
  );
  return byTail?._id || null;
}

export function saveMapState(state) {
  try {
    sessionStorage.setItem(MAP_STATE_KEY, JSON.stringify({ ...state, ts: Date.now() }));
  } catch {
    /* ignore */
  }
}

export function loadMapState() {
  try {
    const raw = sessionStorage.getItem(MAP_STATE_KEY);
    if (!raw) return null;
    const parsed = JSON.parse(raw);
    if (Date.now() - (parsed.ts || 0) > 1000 * 60 * 30) return null;
    return parsed;
  } catch {
    return null;
  }
}

export function buildMapReturnUrl(state) {
  if (!state) return "/";
  const params = new URLSearchParams();
  if (state.lat != null) params.set("lat", state.lat);
  if (state.lng != null) params.set("lng", state.lng);
  if (state.zoom != null) params.set("zoom", state.zoom);
  if (state.issueId) params.set("issue", state.issueId);
  const q = params.toString();
  return q ? `/?${q}` : "/";
}
